"use strict";(globalThis.webpackChunkgrc||=[]).push([[14711],{57944(e){e.exports=JSON.parse('[{"citeKey":"fernandes2026gpuh5","slug":"fernandes-2026-gpuh5-9b21","title":"GPUH5: A GPU-first I/O Library for Scientific Data","authors":["J. Fernandes","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"I/O is a bottleneck in GPU-accelerated science, yet scientific data-format libraries run only on the host. A kernel cannot write where its data lives: it must exit and copy its array before HDF5 can run, so the write point becomes a kernel boundary. Systems that let a GPU initiate I/O give up the data model, emitting flat, untyped byte ranges. We present GPUH5, a GPU-first I/O library for persistent kernels. It keeps HDF5\'s hierarchical paths and chunked arrays, replacing the container format with a key-value store, so the host precomputes every chunk\'s key and an in-kernel write reduces to enqueuing a pointer, light enough that the producer holds 98.8% achieved occupancy. On a single-GPU Gray-Scott simulation writing 380 snapshots to NVMe, GPUH5 hides 96% of the I/O its synchronous twin exposes, finishing 1.9\xd7 faster than default HDF5.","hasAbstract":true,"lede":"We present GPUH5, a GPU-first I/O library for persistent kernels.","links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdsw111&sess=sess129"},"tags":["GPU I/O","HDF5","Scientific Data"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"pawar2026gnnpress","slug":"pawar-2026-gnns-beyond-hbm-3f56","title":"GNNs Beyond HBM: Compressed, Bit-Exact Feature Streaming for Out-of-Core Training","authors":["R. Pawar","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost258&sess=sess313"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"pawar2026acropolis","slug":"pawar-2026-acropolis-1f2a","title":"Acropolis: A Portable, AI-Driven Semantic Search System for HPC","authors":["R. Pawar","L. Logan","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"LLM agents are now a primary interface to data repositories, but they locate files by issuing speculative regex queries through glob, grep, and file reads, creating a guess-and-check loop that is expensive in tool calls and tokens and ignores metadata embedded in scientific file formats. We present Acropolis, a semantic search system that augments a tiered filesystem with adaptive-depth content indexing and exposes it to agents through a typed natural-language interface. Acropolis provides a transparent file-summary operator in the I/O ingest path with content-addressable idempotency, a pluggable search-backend abstraction for lexical, vector, and graph engines, and an MCP server for compatible agents. On a 70-query CMIP6 retrieval benchmark, an agent using Acropolis matches the shell-tool baseline on retrieval accuracy while substantially reducing tool and backend calls per query and LLM token consumption.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2026/pawar-2026-acropolis-1f2a.pdf"},"tags":["Semantic Search","LLM Agents","HPC","Model Context Protocol"],"_projectIds":["iowarp","labios"],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"bateman2026aes","slug":"bateman-2026-agent-error-simulator-3c7d","title":"Agent Error Simulator: Fault Injection for Testing Recovery in Agentic Workflows","authors":["K. Bateman","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Multi-agent large language model (LLM) workflows are increasingly deployed for complex, multi-step computational tasks. Yet the fault tolerance of these systems (how individual agents respond to malformed inputs, tool failures, and subtle numerical errors) remains poorly characterized. We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection. AES intercepts agent-to-model HTTP traffic via a transparent proxy, injecting three categories of faults (format, logic, and tool call) at configurable points in a hierarchical planner-worker-aggregator workflow. We evaluate four models spanning 2B\u201332B parameters (Qwen2.5-Coder 32B, Gemma4 27B, Mistral 7B, and Granite4 2B) across 194 jobs organized into 10 test groups covering baseline behavior, multi-error injection, workflow scale, context pressure, compaction, and detection timing. Our results reveal a model-size-dependent logic error recovery threshold between 7B and 27B parameters; universal catastrophic failure under aggregator-level logic injection; and model-specific aggregator arithmetic deficits that interact with injected faults in non-obvious ways. We release the benchmark suite, injection tooling, and result data to support reproducible multi-agent fault tolerance research.","hasAbstract":true,"lede":"We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection.","links":{"pdf":"https://grc.iit.edu/papers/2026/bateman-2026-agent-error-simulator-3c7d.pdf"},"tags":["LLM Agents","Fault Injection","Resilience","Multi-Agent Workflows"],"_projectIds":["dtio"],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"pawar2026semanticsearch","slug":"pawar-2026-semantic-search-agent-discovery-577f","title":"Benchmarking the Performance of Semantic Search Techniques for Agent Discovery","authors":["R. Pawar","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/Semantic_Search_Poster%20-%20Rajni%20Pawar.pdf"},"_projectIds":["hermes","iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"muradli2025insightsgpudirect","slug":"muradli-2025-insights-gpudirect-02b4","title":"Insights into GPUDirect Data Transfer through NIXL Benchmarking","authors":["I. Muradli","J. Ye","L. Logan","A. Kougkas","X.-H. Sun"],"venue":"21st IEEE International Conference on eScience (eScience \'25), September 15-18, 2025","type":"Technical Report","entryType":"misc","date":"September, 2025","year":2025,"era":"iit","month":9,"doi":"10.1109/escience65000.2025.00075","hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2025/muradli-2025-insights-gpudirect-02b4-poster.pdf"},"tags":["GPU","GPUDirect Storage","NIXL","Benchmarking"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025dtio","slug":"bateman-2025-dtio-e77d","title":"DTIO: Data Stack for AI-driven Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"The 37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3733723.3733736","abstract":"HPC, Big Data Analytics, and Machine Learning have become in- creasingly intertwined as popular models such as LLMs and Diffusion Models have been driving discovery in scientific fields. However, each of these domains has its own storage infrastructure with unique I/O interfaces and storage systems, requiring feature sets that are often incompatible. Users with experience in one domain lack the expertise to change their applications to match the data stacks of the other domains, necessitating expensive conversions. There is a need for a transparent solution for the unification of disparate data stacks for the triple convergence of HPC, Big Data, and ML that can provide the required functionality while achieving higher performance. To better support converged HPC, Big Data, and ML workflows, this paper proposes DTIO, a scalable I/O runtime that unifies the disparate I/O stack for modern scientific ML workflows. DTIO utilizes a unique DataTask abstraction to express the move- ment of data, its ordering, and its dependencies on other data as a task. DTIO achieves a unification of scientific and ML workflows by utilizing intelligent mapping of interfaces, and automatically de- termines the best method to relate their unique semantics. DTIO\'s online translation with DataTask caching can improve performance by 49.6% compared to offline translation methods. DTIO also offers numerous optimizations, such as asynchronous I/O and aggregation.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2025/bateman-2025-dtio-e77d.pdf"},"tags":["Task Systems","Data Stacks","Systems for AI Workflows"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025unifiedstack","slug":"bateman-2025-unified-data-stack-8de5","title":"A Unified Data Stack for AI Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"sathwara2025mcpiowarp","slug":"sathwara-2025-bridging-llms-hpc-deac","title":"Bridging LLMs and HPC: A Modular MCP-IOWarp Framework for Scalable Task Execution","authors":["A. V. Sathwara","J. Cernuda","L. Logan"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://ssdbm.org/2025/assets/poster/6370-Aum-Sathwara.pdf"},"_projectIds":["iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"pawar2025tokenization","slug":"pawar-2025-scaling-data-tokenization-118b","title":"Scaling Data Tokenization for AI Systems","authors":["R. Pawar","L. Logan","X.-H. Sun"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"cernuda2024jarvis","slug":"cernuda-2024-jarvis-3b52","title":"Jarvis: Towards a Shared, User-Friendly, and Reproducible, I/O Infrastructure.","authors":["J. Cernuda","L. Logan","N. Lewis","S. Byna","X.-H. Sun","A. Kougkas"],"venue":"The International Parallel Data Systems Workshop (PDSW\'24)","type":"Workshop","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"abstract":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters. However, computing environments for developing tools to harness these technologies are not easily available to researchers. This work showcases the need for a new high-pace, heterogeneous I/O research cluster and presents a novel software deployment framework named Jarvis to manage its hardware diversity. Jarvis is an extensible Python framework that allows users to create Packages that deploy, manage, and monitor software, including complex applications (e.g., scientific simulations), support tools (e.g., Darshan, GDB), and storage systems (e.g., Lustre, DAOS). These packages can be combined to form complex deployment Pipelines. To ensure pipelines are portable across hardware, Jarvis defines a novel Resource Graph schema file, which is a snapshot of a cluster\'s machine-specific information. This schema can be queried by Jarvis packages to deploy software across diverse hardware compositions with minimal user effort. Index Terms-deployment, HPC, hardware abstraction, resource management, I/O, Python","hasAbstract":true,"lede":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-jarvis-3b52.pdf"},"tags":["Deployment","HPC","Hardware Abstraction","I/O","Python","Resource Management"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2024megammap","slug":"logan-2024-megammap-cbda","title":"MegaMmap: Blurring the Boundary Between Memory and Storage for Data-Intensive Workloads","authors":["L. Logan","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sc41406.2024.00114","abstract":"Large-scale data analytics, scientific simulation, and deep learning codes in HPC perform massive computations on data greatly exceeding the bounds of main memory. These out-of-core al- gorithms suffer from severe data movement penalties, programming complexity, and limited code reuse. To solve this, HPC sites have steadily increased DRAM capacity. However, this is not sustainable due to financial and environmental costs. A more elegant, low-cost, and portable solution is to expand memory to distributed multi- tiered storage. In this work, we propose MegaMmap: a software distributed shared memory (DSM) that enlarges effective memory capacity through intelligent tiered DRAM and storage management. MegaMmap provides workload-aware data organization, eviction, and prefetching policies to reduce DRAM consumption while ensur- ing speedy access to critical data. A variety of memory coherence optimizations are provided through an intuitive hinting system. Evaluations show that various workloads can be executed with a fraction of the DRAM while offering competitive performance.","hasAbstract":true,"lede":"We propose MegaMmap: a software distributed shared memory (DSM) that enlarges effective memory capacity through intelligent tiered DRAM and storage management.","links":{"pdf":"https://grc.iit.edu/papers/2024/logan-2024-megammap-cbda.pdf","code":"https://github.com/grc-iit/mega_mmap"},"tags":["Memory","Storage","Hierarchical Storage","HPC","Operating Systems","LABIOS"],"_projectIds":["labios"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2024evaluationdaos","slug":"logan-2024-evaluation-daos-6eb2","title":"An Evaluation of DAOS for Simulation and Deep Learning HPC Workloads","authors":["L. Logan","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"SIGOPS Operating Systems Review (OSR\'24)","type":"Journal","entryType":"article","date":"June, 2024","year":2024,"era":"iit","month":6,"doi":"10.1145/3689051.3689058","abstract":"Traditionally, distributed storage systems have relied upon the interfaces provided by OS kernels to interact with stor- age hardware. However, much research has shown that OSes impose serious overheads on every I/O operation, especially on high-performance storage and networking hardware (e.g., PMEM and 200GBe). Thus, distributed storage stacks are being re-designed to take advantage of this modern hard- ware by utilizing new hardware interfaces which bypass the kernel entirely. However, the impact of these optimizations have not been well-studied for real HPC workloads on real hardware. In this work, we provide a comprehensive evalua- tion of DAOS: a state-of-the-art distributed storage system which re-architects the storage stack from scratch for mod- ern hardware. We compare DAOS against traditional storage stacks and demonstrate that by utilizing optimal interfaces to hardware, performance improvements of up to 6x can be observed in real scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/logan-2024-evaluation-daos-6eb2.pdf"},"tags":["Distributed Computing","Distributed Storage","Flash Memory","Machine Learning","Parallel Computing","Phase Change Memory"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2024hades","slug":"cernuda-2024-hades-e18c","title":"Hades: A Context-Aware Active Storage Framework for Accelerating Large-Scale Data Analysis","authors":["J. Cernuda","L. Logan","A. Gainaru","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 24th IEEE/ACM international Symposium on Cluster, Cloud and Internet Computing (CCGRID 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ccgrid59990.2024.00070","abstract":"Modern simulation workflows generate and analyze massive amounts of data using I/O libraries like Adios2 and NetCDF. Although extensive work has optimized the I/O processes during the simulation phase, executing analytical queries-which often require iterative traversals of large files for insights-is cumbersome and usually constrained by low I/O performance. Instead of waiting for the analysis phase to process queries, quantities can be derived asynchronously during data production and cached, speeding up future queries. In this work, we introduce a context-aware I/O layer named \'Hades.\' It is designed to efficiently derive insights from selected quantities without compromising overall workflow performance. Hades actively and asynchronously computes and stores these quantities while the data is in transit. Hades leverages a hierarchical buffering system with data access-aware prefetching to ensure quick and timely access to relevant data. It offers a flexible query interface empowering users to easily define derived quantities and provide control over data placement decisions. Hades is implemented using an Adios2 plugin engine and the Hermes buffering platform, enabling transparent use by any Adios-powered application or workflow. Experimental results demonstrate performance improvements by up to 3-4x for tested real-world scientific producer-consumer workflows. Index Terms-Active Storage, Hierarchical Storage, Context Awareness, Metadata Management, Data Operator, In-transit Computing","hasAbstract":true,"lede":"We introduce a context-aware I/O layer named \'Hades.\'","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hades-e18c.pdf"},"tags":["Active Storage","Hierarchical Storage","Context Awareness","Metadata Management","Data Operator","In-Transit Computing","Coeus"],"_projectIds":["coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2023evaluationdaos","slug":"logan-2023-evaluation-daos-a960","title":"An Evaluation of DAOS for Simulation and Deep Learning HPC Workloads","authors":["L. Logan","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 3rd Workshop on Challenges and Opportunities of Efficient and Performant Storage Systems (CHEOPS\'23)","type":"Workshop","entryType":"inproceedings","date":"May, 2023","year":2023,"era":"iit","month":5,"doi":"10.1145/3578353.3589542","abstract":"Traditionally, distributed storage systems have relied upon the interfaces provided by OS kernels to interact with stor- age hardware. However, much research has shown that OSes impose serious overheads on every I/O operation, especially on high-performance storage and networking hardware (e.g., PMEM and 200GBe). Thus, distributed storage stacks are being re-designed to take advantage of this modern hard- ware by utilizing new hardware interfaces which bypass the kernel entirely. However, the impact of these optimizations have not been well-studied for real HPC workloads on real hardware. In this work, we provide a comprehensive evalua- tion of DAOS: a state-of-the-art distributed storage system which re-architects the storage stack from scratch for mod- ern hardware. We compare DAOS against traditional storage stacks and demonstrate that by utilizing optimal interfaces to hardware, performance improvements of up to 6x can be observed in real scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2023/logan-2023-evaluation-daos-a960.pdf"},"tags":["Distributed Computing","Distributed Storage","Flash Memory","Machine Learning","Parallel Computing","Phase Change Memory"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2022luxio","slug":"bateman-2022-luxio-2487","title":"LuxIO: Intelligent Resource Provisioning and Auto-Configuration for Storage Services","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","J. Ye","S. Herbein","A. Kougkas","X.-H. Sun"],"venue":"The 29th edition of the IEEE International Conference on High Performance Computing, Data, and Analytics (HiPC\'22)","type":"Conference","entryType":"inproceedings","date":"December, 2022","year":2022,"era":"iit","month":12,"doi":"10.1109/hipc56025.2022.00041","abstract":"Abstract-Storage in HPC is typically a single Remote and Static Storage (RSS) resource. However, applications demonstrate diverse I/O requirements that can be better served by a multi-storage approach. Cur- rent practice employs ephemeral storage systems running on either node- local or shared storage resources. Yet, the burden of provisioning and configuring intermediate storage falls solely on the users, while global job schedulers offer little to no support for custom deployments. This lack of support often leads to over- or under-provisioning of resources and poorly configured storage systems. To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service. LuxIO constructs storage deployments configured to best match I/O require- ments. LuxIO-tuned storage services show performance improvements up to 2x across common applications and benchmarks, while introducing minimal overhead of 93.40 ms on top of existing job scheduling pipelines. LuxIO improves resource utilization by up to 25% in select workflows.","hasAbstract":true,"lede":"To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service.","links":{"pdf":"https://grc.iit.edu/papers/2022/bateman-2022-luxio-2487.pdf"},"tags":["Resource Provisioning","I/O Behavior","Storage Auto-Tuning","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2022labstor","slug":"logan-2022-labstor-f69d","title":"LabStor: A Modular and Extensible Platform for Developing High-Performance, Customized I/O Stacks in Userspace","authors":["L. Logan","J. Cernuda","J. Lofstead","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Conference","entryType":"inproceedings","date":"November, 2022","year":2022,"era":"iit","month":11,"doi":"10.1109/sc41404.2022.00028","abstract":"Traditionally, I/O systems have been developed within the confines of a centralized OS kernel. This led to monolithic and rigid storage systems that are limited by low development speed, expressiveness, and performance. Various assumptions are imposed including reliance on the UNIX-file abstraction, the POSIX standard, and a narrow set of I/O policies. However, this monolithic design philosophy makes it difficult to develop and deploy new I/O approaches to satisfy the rapidly-evolving I/O requirements of modern scientific applications. To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks. Single-purpose I/O modules (e.g, I/O schedulers) can be developed in the comfort of userspace and released as plug-ins, while end-users can compose these modules to form workload- and hardware-specific I/O stacks. Evaluations show that by switching to a fully modular design, tailored I/O stacks can yield performance improvements of up to 60% in various applications.","hasAbstract":true,"lede":"To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks.","links":{"pdf":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d.pdf","slides":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d-slides.pdf"},"tags":["Clouds and Distributed Computing","Programming Frameworks","System Software","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2021utilizingpersistent","slug":"logan-2021-utilizing-persistent-24d5","title":"Utilizing Persistent Memory in Parallel I/O Libraries","authors":["L. Logan","J. Lofstead","S. Levy","P. Widener","X.-H. Sun","A. Kougkas"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/logan-2021-utilizing-persistent-24d5.pdf","poster":"https://grc.iit.edu/papers/2021/logan-2021-utilizing-persistent-24d5-poster.pdf"},"tags":["Persistent Memory","Libraries","Memory Management","Memory Mapped I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2021hflow","slug":"cernuda-2021-hflow-2f5b","title":"HFlow: A Dynamic and Elastic Multi-Layered Data Forwarder","authors":["J. Cernuda","H. Devarajan","L. Logan","K. Bateman","N. Rajesh","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Conference","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00064","abstract":"Modern applications are highly data-intensive, leading to the well-known I/O bottleneck problem. Scientists have proposed the placement of fast intermediate storage resources which aim to mask the I/O penalties. To manage these resources, three core software abstractions are being used in leadership-class computing facilities: IO Forwarders, Burst Buffers, and Data Stagers. Yet, with the rise of multi-tenant deployment in HPC systems, these software abstractions are: managed and maintained in isolation, leading to inefficient interactions; allocated statically, leading to load imbalance; exclusively bifurcated between the intermediate storage, leading to under-utilization of resources, and, in many cases, do not support in-situ operations. To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm. HFlow introduces a unified data movement abstraction (the ByteFlow) providing data-independent tasks that can be executed anywhere and thus, enabling dynamic resource provisioning. Moreover, the processing elements executing the ByteFlows are designed to be ephemeral and, hence, enable elastic management of intermediate storage resources. Our results show that applications running under HFlow display an increase in performance of 3x when compared with state-of-the-art software solutions. Index Terms-Data streaming, I/O forwarding, elasticity, dynamicity, multi-tenant, data-intensive, I/O,data pipeline, in-transit","hasAbstract":true,"lede":"To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm.","links":{"pdf":"https://grc.iit.edu/papers/2021/cernuda-2021-hflow-2f5b.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2021pmemcpy","slug":"logan-2021-pmemcpy-f81c","title":"pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory","authors":["L. Logan","J. Lofstead","S. Levy","P. Widener","X.-H. Sun","A. Kougkas"],"venue":"The 1st Workshop on Re-envisioning Extreme-Scale I/O for Emerging Hybrid HPC Workloads (REX-IO\'21), in conjunction with the 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Workshop","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00098","abstract":"Persistent memory (PMEM) devices can achieve comparable performance to DRAM while providing significantly more capacity. This has made the technology compelling as an expansion to main memory. Rethinking PMEM as storage devices can offer a high performance buffering layer for HPC applications to temporarily, but safely store data. However, modern parallel I/O libraries, such as HDF5 and pNetCDF, are complicated and introduce significant software and metadata overheads when persisting data to these storage devices, wasting much of their potential. In this work, we explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory. We demonstrate that our approach is up to 2x faster than other popular parallel I/O libraries under real workloads.","hasAbstract":true,"lede":"We explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory.","links":{"pdf":"https://grc.iit.edu/papers/2021/logan-2021-pmemcpy-f81c.pdf"},"tags":["Persistent Memory","Libraries","Memory Management","Memory Mapped I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2021apollo","slug":"rajesh-2021-apollo-dbd8","title":"Apollo: An ML-assisted Real-Time Storage Resource Observer","authors":["N. Rajesh","H. Devarajan","J. Cernuda","K. Bateman","L. Logan","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 30th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'21), June 21-25, 2021","type":"Conference","entryType":"inproceedings","date":"June, 2021","year":2021,"era":"iit","month":6,"doi":"10.1145/3431379.3460640","abstract":"Applications and middleware services, such as data placement en- gines, I/O scheduling, and prefetching engines, require low-latency access to telemetry data in order to make optimal decisions. However, typical monitoring services store their telemetry data in a database in order to allow applications to query them, resulting in significant latency penalties. This work presents Apollo: a low-latency mon- itoring service that aims to provide applications and middleware libraries with direct access to relational telemetry data. Monitoring the system can create interference and overhead, slowing down raw performance of the resources for the job. However, having a current view of the system can aid middleware services in making more optimal decisions which can ultimately improve the overall perfor- mance. Apollo has been designed from the ground up to provide low latency, using Publish\u2013Subscribe (Pub-Sub) semantics, and low overhead, using adaptive intervals in order to change the length of time between polling the resource for telemetry data and machine learning in order to predict changes to the telemetry data between actual resource polling. This work also provides some high level abstractions called I/O curators, which can further aid middleware libraries and applications to make optimal decisions. Evaluations showcase that Apollo can achieve sub-millisecond latency for acquir- ing complex insights with a memory overhead of 57MB and CPU overhead being only 7% more than existing state-of-the-art systems.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2021/rajesh-2021-apollo-dbd8.pdf"},"tags":["HPC","Machine Learning","Resource Monitoring","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2020quantifyingoverheads","slug":"logan-2020-quantifying-overheads-cfc2","title":"Quantifying the Overheads of the Modern Linux I/O Stack","authors":["L. Logan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'20)","type":"Poster","entryType":"misc","date":"November, 2020","year":2020,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2020/logan-2020-quantifying-overheads-cfc2.pdf","poster":"https://grc.iit.edu/papers/2020/logan-2020-quantifying-overheads-cfc2-poster.pdf"},"tags":["I/O Bottleneck","Filesystems","Linux"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hcompress","slug":"devarajan-2020-hcompress-70f7","title":"HCompress: Hierarchical Data Compression for Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","L. Logan","X.-H. Sun"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\'20), May 18-22, 2020","type":"Conference","entryType":"inproceedings","date":"May, 2020","year":2020,"era":"iit","month":5,"doi":"10.1109/ipdps47924.2020.00064","abstract":"Modern scientific applications read and write massive amounts of data through simulations, observations, and analysis. These applications spend the majority of their runtime in performing I/O. HPC storage solutions include fast node-local and shared storage resources to elevate applications from this bottleneck. Moreover, several middleware libraries (e.g., Hermes) are proposed to move data between these tiers transparently. Data reduction is another technique that reduces the amount of data produced and, hence, improve I/O performance. These two technologies, if used together, can benefit from each other. The effectiveness of data compression can be enhanced by selecting different compression algorithms according to the characteristics of the different tiers, and the multi-tiered hierarchy can benefit from extra capacity. In this paper, we design and implement HCompress, a hierarchical data compression library that can improve the application\'s performance by harmoniously leveraging both multi-tiered storage and data compression. We have developed a novel compression selection algorithm that facilitates the optimal matching of compression libraries to the tiered storage. Our evaluation shows that HCompress can improve scientific application\'s performance by 7x when compared to other state-of-the-art tiered storage solutions.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7-slides.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Compression","Data-Reduction","Dynamic Choice","Workflow Priorities","Library","Middleware","Engine","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);